<template>
  <main class="workbench">
    <header class="wb-head"><div><span class="wb-kicker">LABEL STANDARDS</span><h1>标注标准库</h1><p>先说明什么应该标、什么不应该标。发布后形成不可变版本，可独立复用和试标。</p></div><button :disabled="busy" @click="newDraft">新建标准</button></header>
    <ScenarioPath current="/label-standards" />
    <p v-if="error" class="wb-error" role="alert">{{ error }}</p><p v-if="notice" class="wb-success" role="status">{{ notice }}</p>
    <div class="wb-grid"><aside class="wb-panel"><h2>标准草稿</h2><div class="wb-list"><button v-for="item in items" :key="item.id" :disabled="busy" :class="{selected:current?.id===item.id}" @click="open(item.id)"><strong>{{ item.name }}</strong><small>{{ standardTypeLabels[item.task_type] }} · 修订 {{ item.version }} · {{ item.latest_version_id?'已有发布版本':'尚未发布' }}</small></button></div><p v-if="!items.length" class="wb-empty">暂无标准，创建后可保存草稿，再显式发布。</p><button v-if="next" :disabled="busy" @click="load(true)">更多标准</button></aside>
    <div class="wb-stack"><form class="wb-panel wb-stack" @submit.prevent="save"><h2>{{ current?'编辑草稿':'新建标准' }}</h2><fieldset :disabled="busy" class="scenario-fieldset"><div class="wb-form"><label>标准名称<input v-model="draft.name" required maxlength="128" /></label><label>任务类型<select aria-label="任务类型" v-model="draft.task_type" @change="changeType"><option v-for="(text,type) in standardTypeLabels" :key="type" :value="type">{{ text }}</option></select></label><label class="wb-full">总则与判定规则<textarea v-model="draft.guidelines" maxlength="12000" required /></label><label v-if="['classification','tagging'].includes(draft.task_type)">最多标签数<input v-model.number="draft.constraints.max_labels" type="number" min="1" :max="limit" required /></label><label v-if="['named_entity','relation','tagging'].includes(draft.task_type)">最多实体数<input v-model.number="draft.constraints.max_entities" type="number" :min="draft.task_type==='tagging'?0:1" max="1000" required /></label><label v-if="draft.task_type==='relation'">最多关系数<input v-model.number="draft.constraints.max_relations" type="number" min="1" max="1000" required /></label><label v-if="draft.task_type!=='qa'" class="wb-checkbox"><input v-model="draft.constraints.allow_empty" type="checkbox" />允许空标注通过审核</label></div>
    <template v-if="draft.task_type!=='qa'"><div class="wb-section-head"><h3>标签定义（{{ draft.labels.length }}/{{ limit }}）</h3><button type="button" :disabled="draft.labels.length>=limit" @click="addLabel">添加标签</button></div><p class="wb-footnote">标签 ID 在版本内唯一。关键词和实体词条用于规则建议；定义、边界和样例用于人工及模型审阅。所有候选仍需审核。</p>
    <details v-for="(label,index) in draft.labels" :key="index" class="standard-label" :open="draft.labels.length===1"><summary>{{ index+1 }}. {{ label.name || '未命名标签' }}</summary><div class="wb-form"><label>标签 ID<input v-model="label.id" required /></label><label>标签名称<input v-model="label.name" required /></label><label class="wb-full">定义<textarea v-model="label.definition" required /></label><label v-for="field in ruleFields" :key="field.key">{{ field.title }}（每行一项）<textarea :value="(label[field.key]||[]).join('\n')" @change="label[field.key]=lines(($event.target as HTMLTextAreaElement).value)" /></label></div><div class="wb-section-head"><h3>正反例</h3><button type="button" @click="label.examples.push({text:'',decision:'include',explanation:''})">添加样例</button></div><div v-for="(example,j) in label.examples" :key="j" class="wb-form"><label>样例原文<textarea v-model="example.text" required /></label><label>结论<select v-model="example.decision"><option value="include">应标此标签</option><option value="exclude">不应标此标签</option></select></label><label>解释<input v-model="example.explanation" required /></label><button type="button" @click="label.examples.splice(j,1)">删除样例</button></div><button type="button" class="danger" @click="draft.labels.splice(index,1)">删除标签</button></details>
    <details><summary>批量导入标签定义</summary><p class="wb-footnote">粘贴 StandardLabel JSON 数组，仅替换当前草稿标签；不会保存或发布。</p><textarea v-model="bulk" aria-label="标签定义 JSON" /><button type="button" @click="importLabels">校验并填入草稿</button></details>
    </template><p v-else class="wb-footnote">问答标准不定义标签，问题与参考答案均必须来自真实映射列。</p>
    <div class="wb-actions"><button class="primary" type="submit">{{ busy?'正在保存…':'保存草稿' }}</button><button v-if="current" type="button" :disabled="dirty" @click="publish">发布此修订</button></div><p v-if="dirty&&current" class="wb-footnote">有未保存修改。先保存草稿，再发布此修订。</p></fieldset></form>
    <section v-if="current" class="wb-panel"><h2>已发布版本</h2><p class="wb-footnote">发布不会自动创建标注任务。试标在标注页选择已有准备数据，显式创建，再生成规则或模型建议。</p><div class="wb-list"><div v-for="version in versions" :key="version.id" class="standard-version"><strong>修订 {{ version.standard_revision }} · {{ version.name }}</strong><p class="wb-footnote">{{ version.id }} · {{ version.content_digest }}</p><RouterLink :to="{path:'/labeling',query:{standard_version_id:version.id,kind:version.task_type==='tagging'?'tagging':'annotation'}}">使用此版本 / 试标</RouterLink><RouterLink v-if="version.task_type==='qa'" :to="{path:'/sft-datasets',query:{standard_version_id:version.id}}">构建 SFT 数据集</RouterLink></div></div><p v-if="!versions.length" class="wb-empty">尚无已发布版本。</p><button v-if="versionNext" :disabled="busy" @click="moreVersions">更多已发布版本</button></section></div></div>
  </main>
</template>
<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue'
import { useRoute,onBeforeRouteLeave } from 'vue-router'
import { standardsApi,standardTypeLabels,type LabelStandard,type StandardInput,type StandardVersion,type StandardLabel } from '@/api/governance/standards'
import ScenarioPath from './ScenarioPath.vue'
import { useScenarioSession } from './useScenarioSession'
import '@/components/workbench/workbench.css'
import './scenario.css'
const route=useRoute(),items=ref<LabelStandard[]>([]),next=ref(''),current=ref<LabelStandard>(),versions=ref<StandardVersion[]>([]),versionNext=ref(''),bulk=ref('')
const empty=():StandardInput=>({name:'',task_type:'classification',guidelines:'',labels:[],constraints:{max_labels:1,max_entities:0,max_relations:0,allow_empty:true}})
const draft=ref(empty()),baseline=ref(JSON.stringify(draft.value)),dirty=computed(()=>baseline.value!==JSON.stringify(draft.value)),limit=computed(()=>draft.value.task_type==='tagging'?30:100)
const session=useScenarioSession(()=>{items.value=[];next.value='';newDraft();void initialize()}),{busy,error,notice}=session
const lines=(s:string)=>s.split('\n').map(v=>v.trim()).filter(Boolean)
const ruleFields=[{key:'include_criteria',title:'纳入条件'},{key:'exclude_criteria',title:'排除条件'},{key:'keywords',title:'匹配关键词'},{key:'terms',title:'实体词条'},{key:'exclude_keywords',title:'排除关键词'}] as const
const copyInput=(s:StandardInput):StandardInput=>JSON.parse(JSON.stringify({name:s.name,task_type:s.task_type,guidelines:s.guidelines,labels:(s.labels||[]).map(label=>({...label,include_criteria:label.include_criteria||[],exclude_criteria:label.exclude_criteria||[],keywords:label.keywords||[],terms:label.terms||[],exclude_keywords:label.exclude_keywords||[],examples:label.examples||[]})),constraints:s.constraints}))
function reset(){current.value=undefined;versions.value=[];versionNext.value='';draft.value=empty();baseline.value=JSON.stringify(draft.value);bulk.value=''}
function newDraft(){session.invalidate();reset()}
function changeType(){const type=draft.value.task_type;draft.value.labels=[];draft.value.constraints={max_labels:['classification','tagging'].includes(type)?1:0,max_entities:['named_entity','relation','tagging'].includes(type)?30:0,max_relations:type==='relation'?30:0,allow_empty:type!=='qa'}}
function addLabel(){draft.value.labels.push({id:'',name:'',definition:'',include_criteria:[],exclude_criteria:[],keywords:[],terms:[],exclude_keywords:[],examples:[]})}
function importLabels(){try{const value:unknown=JSON.parse(bulk.value);if(!Array.isArray(value)||value.length>limit.value)throw new Error('标签数组数量不符合限制');const mapped=value.map((item:unknown)=>{if(!item||typeof item!=='object')throw new Error('标签必须为对象');const l=item as StandardLabel;if(['id','name','definition'].some(k=>typeof l[k as keyof StandardLabel]!=='string')||ruleFields.some(f=>!Array.isArray(l[f.key])||l[f.key].some(v=>typeof v!=='string'))||!Array.isArray(l.examples)||l.examples.some(e=>!e||typeof e.text!=='string'||typeof e.explanation!=='string'||!['include','exclude'].includes(e.decision)))throw new Error('标签缺少定义、规则数组或有效正反例');return l});draft.value.labels=mapped;error.value=''}catch(e){error.value=e instanceof Error?e.message:'JSON 无效'}}
async function load(append=false){await session.run(async valid=>{const r=await standardsApi.list(append?next.value:'');if(!valid())return;items.value=Array.from(new Map([...(append?items.value:[]),...(r.data?.items||[])].map(v=>[v.id,v])).values());next.value=r.data?.next_cursor||''})}
async function readVersions(id:string,valid:()=>boolean,append=false){const r=await standardsApi.versions(id,append?versionNext.value:'');if(!valid())return;versions.value=Array.from(new Map([...(append?versions.value:[]),...(r.data?.items||[])].map(v=>[v.id,v])).values());versionNext.value=r.data?.next_cursor||''}
async function open(id:string){if(dirty.value&&!window.confirm('放弃当前未保存的标准草稿？'))return;session.invalidate();reset();await session.run(async valid=>{const r=await standardsApi.get(id);if(!valid())return;if(!r.data)throw new Error('标准不存在或无权访问');current.value=r.data;draft.value=copyInput(r.data);baseline.value=JSON.stringify(draft.value);await readVersions(id,valid)})}
async function save(){await session.run(async valid=>{const input=copyInput(draft.value);if(input.labels.length>limit.value)throw new Error('标签数超出当前类型上限');const r=current.value?await standardsApi.update(current.value.id,current.value.version,input):await standardsApi.create(input);if(!valid())return;if(!r.data)throw new Error('未收到已保存的标准');current.value=r.data;draft.value=copyInput(r.data);baseline.value=JSON.stringify(draft.value);items.value=Array.from(new Map([...items.value,r.data].map(v=>[v.id,v])).values());notice.value='草稿已保存；尚未发布。'})}
async function publish(){if(!current.value||dirty.value)return;const id=current.value.id,version=current.value.version;await session.run(async valid=>{await standardsApi.publish(id,version);if(!valid())return;const r=await standardsApi.get(id);if(!valid())return;current.value=r.data;await readVersions(id,valid);if(valid())notice.value='版本已发布，可显式创建标注任务或 SFT 数据集。'})}
async function moreVersions(){if(current.value)await session.run(valid=>readVersions(current.value!.id,valid,true))}
async function initialize(){const valid=session.capture();await load();if(valid()&&typeof route.query.standard_id==='string')await open(route.query.standard_id)}
watch(()=>route.query.standard_id,id=>{if(typeof id==='string')void open(id)})
onBeforeRouteLeave(()=>!dirty.value||window.confirm('标准草稿尚未保存，仍要离开吗？'))
onMounted(initialize)
</script>
